import{_ as e,o,c as t,a0 as r}from"./chunks/framework.IrjkP_YN.js";const u=JSON.parse('{"title":"这个项目一半代码是 AI 写的","description":"","frontmatter":{},"headers":[],"relativePath":"posts/ai-wrote-half.md","filePath":"posts/ai-wrote-half.md","lastUpdated":null}'),n={name:"posts/ai-wrote-half.md"};function p(i,a,l,s,c,d){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="这个项目一半代码是-ai-写的" tabindex="-1">这个项目一半代码是 AI 写的 <a class="header-anchor" href="#这个项目一半代码是-ai-写的" aria-label="Permalink to &quot;这个项目一半代码是 AI 写的&quot;">​</a></h1><p>2026-09</p><p>先说结论，免得你觉得我在藏什么。</p><p><strong>前端我基本是从零让 AI 生成的。</strong> 我能读懂、能改、能联调，但让我关掉 AI 从空白文件开始手写一个 Vue 页面，我写不出来。</p><p><strong>后端这条商标规则引擎的线，设计决定是我做的，代码有不少也是 AI 帮我落的。</strong></p><p>我把它写在简历上了，也打算在面试里就这么说。下面讲讲我为什么觉得这样不算作弊，以及哪些地方我自己也心虚。</p><h2 id="哪些是我想的" tabindex="-1">哪些是我想的 <a class="header-anchor" href="#哪些是我想的" aria-label="Permalink to &quot;哪些是我想的&quot;">​</a></h2><p>举三个，都是能被追问的。</p><p><strong>一、法条为什么存数据库不存代码里。</strong></p><p>因为我查出来商标法 2026 年修订、2027 年 1 月 1 日施行，禁止性标志那条会从第十条搬到第十五条，写在代码里的条款号四个多月后就废了。这个是我自己搜到的。AI 一开始还跟我说「这一类不需要外部数据」，是我后来发现不对——第十条要判「同国家名称、红十字红新月相同或近似」，这些得有名录。</p><p><strong>二、为什么模型只能输出条款 id，不能输出条款原文。</strong></p><p>因为我不想给它改字的机会。这个决定的来处是我抓到过一次它编诗词出处，<a href="./hallucination.html">另一篇写了</a>。</p><p><strong>三、同一个条款被规则和模型同时命中，要不要去重。</strong></p><p>我选了不去重，改成按条款聚合成一条、条里面留多个来源。</p><p>理由是「五星红旗中国红」这种名字：「五星红旗」和「中国」属于两个不同类别，但都映射到第十条第一款第（一）项。按条款去重会吃掉一条真命中，而且<strong>是静默的</strong>——界面上少一条，不报任何错。</p><h2 id="哪些不是" tabindex="-1">哪些不是 <a class="header-anchor" href="#哪些不是" aria-label="Permalink to &quot;哪些不是&quot;">​</a></h2><ul><li>前端所有页面</li><li>后端很多具体实现。SQLAlchemy 那些 <code>Mapped</code> 注解、alembic 迁移、pydantic 的跨字段校验，我第一次写都是让 AI 给了形状我再改</li><li>Docker 和 nginx 配置</li></ul><h2 id="一个反过来的收获" tabindex="-1">一个反过来的收获 <a class="header-anchor" href="#一个反过来的收获" aria-label="Permalink to &quot;一个反过来的收获&quot;">​</a></h2><p>AI 写代码会犯一些很具体的错，而且<strong>它自己不知道</strong>。我抓到过几次：</p><ul><li>它跟我说「在一个已经绑了工具的模型上再绑一次，是叠加不是替换」。我觉得不对，让它跑了个实验，结果<strong>是替换</strong>，它说错了</li><li>它在服务层写了个 <code>raise SystemExit</code>。这个是我自己发现的——<code>SystemExit</code> 继承 <code>BaseException</code>，会穿过 asyncio 把整个 uvicorn 进程杀掉。一次性脚本里这么写没问题（死得响），长驻服务里这么写就是整个后端挂掉</li><li>它给我写的测试脚本里，喂回给模型的工具结果是空的，它自己没发现，还差点把这个当成「模型正确地把出处填成了 null」的证据报给我</li></ul><p>所以现在我的习惯是：<strong>它说的每一句关于「会发生什么」的话，我都让它跑一次给我看。</strong> 不跑就当没说。</p><p>这条是我踩出来的。我有个毛病是「写了那个东西就以为它起作用了」——写了 <code>logger.error(&quot;超时&quot;)</code> 就以为超时被处理了，写了 <code>tool_choice=&#39;required&#39;</code> 就以为强制生效了。AI 也有这个毛病，而且它写得更自信。</p><h2 id="我心虚的地方" tabindex="-1">我心虚的地方 <a class="header-anchor" href="#我心虚的地方" aria-label="Permalink to &quot;我心虚的地方&quot;">​</a></h2><p>两个。</p><p>一个是<strong>手感</strong>。我能看懂 AI 写的异步代码，但让我从空白文件开始写一个 agent 循环，我得想很久。这个只能靠多写，没有别的办法。</p><p>另一个是<strong>前端</strong>。我简历上早先把 Vue 那条技能删了，就是这个原因。面试要是问我前端细节，我会直接说「前端是 AI 辅助实现的，我负责需求、联调和后期维护，我的重心一直在后端」。我不打算装。</p><h2 id="所以这算作弊吗" tabindex="-1">所以这算作弊吗 <a class="header-anchor" href="#所以这算作弊吗" aria-label="Permalink to &quot;所以这算作弊吗&quot;">​</a></h2><p>我觉得不算，但我也不打算说这是我一行行敲的。</p><p>用 AI 写代码跟用 IDE 自动补全差不多，没人觉得自动补全是作弊。区别在于：<strong>补全帮你省手指，AI 帮你省脑子。省手指没问题，省脑子有问题——省掉的脑子会在面试的时候找回来。</strong></p><p>所以我给自己定了条底线：可以让它写，但每一个「为什么这么设计」我必须自己答得上来。答不上来的，就说明这块不是我的，我就不往简历上写。</p><p>我删过一条「计算机设计大赛三等奖」，就是因为那个是我混的，答不住追问。同一个道理。</p><hr><p>这篇可能有人觉得我在给自己找台阶。也许是。</p><p>但我更怕另一种情况：项目看起来很牛，面试官问三层我就答不上来了。那比一开始就说清楚难看得多。</p>',34)])])}const g=e(n,[["render",p]]);export{u as __pageData,g as default};
